from __future__ import annotations
from html import escape

HEAD = '''<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#08090d"><title>Technamooz Control</title><style>
@import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;600&family=Vazirmatn:wght@300;400;500;600;700;800&display=swap');
:root{--bg:#07080c;--p:rgba(17,19,27,.82);--p2:#181b25;--l:rgba(255,255,255,.1);--t:#f7f8fb;--m:#969cab;--r:#ff3650;--r2:#a60e28;--g:#35d39a;--y:#f2c96d}*{box-sizing:border-box}body{margin:0;background:radial-gradient(900px 500px at 80% -10%,#79152b55,transparent 65%),radial-gradient(700px 500px at 0 110%,#49266d33,transparent 65%),var(--bg);color:var(--t);font-family:Vazirmatn,system-ui,sans-serif;min-height:100vh}button,input,select{font:inherit}button{cursor:pointer}.glass{background:var(--p);border:1px solid var(--l);box-shadow:0 25px 70px #0006;backdrop-filter:blur(18px)}.mono{font-family:'IBM Plex Mono',monospace;direction:ltr;text-align:left}.muted{color:var(--m)}.red{color:var(--r)}.logo{display:flex;gap:11px;align-items:center;font-weight:800}.mark{width:42px;height:42px;border-radius:14px;display:grid;place-items:center;background:linear-gradient(145deg,var(--r),#710b22);font-family:'IBM Plex Mono';box-shadow:0 8px 28px #ff365044}.btn{border:1px solid var(--l);border-radius:11px;background:#ffffff0b;color:var(--t);padding:10px 14px;transition:.2s}.btn:hover{border-color:#ff365099;transform:translateY(-1px)}.primary{background:linear-gradient(135deg,var(--r),var(--r2));border:0}.input,.select{width:100%;padding:12px;background:#0004;border:1px solid var(--l);border-radius:10px;color:var(--t);outline:0}.input:focus,.select:focus{border-color:var(--r)}
/* terminal */.terminal{width:min(960px,calc(100% - 28px));margin:7vh auto;border-radius:22px;overflow:hidden}.termbar{padding:14px 18px;border-bottom:1px solid var(--l);display:flex;justify-content:space-between;align-items:center;background:#ffffff08}.dots{display:flex;gap:7px}.dots i{width:10px;height:10px;border-radius:50%;background:#ff5369}.dots i:nth-child(2){background:#e9bd61}.dots i:nth-child(3){background:#39c88e}.termbody{padding:32px;min-height:450px;background:#05060999}.term-title{font-size:26px;font-weight:800;margin:30px 0 8px}.termline{font:13px/2 'IBM Plex Mono';direction:ltr;text-align:left;color:#dfe2ea}.termline b{color:var(--g)}.prompt{display:flex;gap:10px;align-items:center;border-top:1px solid var(--l);padding-top:18px;margin-top:28px}.prompt span{color:var(--r);font:13px 'IBM Plex Mono';direction:ltr}.prompt input{flex:1;background:none;border:0;color:#fff;outline:0;font:14px 'IBM Plex Mono';direction:ltr}.terminal-help{color:var(--m);font-size:12px;line-height:2;margin-top:20px}.langs button{background:none;border:0;color:var(--m)}.langs .active{color:var(--r)}
/* app */.app{display:flex;min-height:100vh}.side{width:248px;padding:22px 15px;border-left:1px solid var(--l);background:#07080ccc;display:flex;flex-direction:column;gap:25px;flex:none}.navs{display:grid;gap:7px}.nav{border:1px solid transparent;background:none;color:var(--m);padding:12px;border-radius:12px;text-align:right;display:flex;gap:11px}.nav:hover,.nav.active{color:#fff;background:#ff365016;border-color:#ff365033}.nav strong{font-size:12px;font-weight:500}.foot{margin-top:auto;border-top:1px solid var(--l);padding-top:15px}.content{padding:25px 30px;flex:1;min-width:0}.top{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:24px}.title{font-size:25px;margin:0 0 5px}.subtitle{font-size:13px;margin:0;color:var(--m)}.actions{display:flex;gap:8px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.card{padding:18px;border-radius:16px}.icon{width:38px;height:38px;border-radius:12px;background:#ff36501a;color:var(--r);display:grid;place-items:center;font-family:'IBM Plex Mono'}.num{font-size:27px;font-weight:800;margin-top:10px}.label{color:var(--m);font-size:12px}.section{margin-top:18px}.section-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.section-title{font-weight:700;font-size:15px}.table-wrap{overflow:auto;border-radius:16px}.table{width:100%;min-width:720px;border-collapse:collapse}.table th,.table td{padding:13px 15px;border-bottom:1px solid var(--l);font-size:12px;text-align:right;white-space:nowrap}.table th{color:var(--m);background:#ffffff06;font-weight:500}.pill{display:inline-flex;padding:4px 8px;border-radius:99px;background:#35d39a1a;color:var(--g);font-size:11px}.pill.off{background:#fff1;color:var(--m)}.empty{text-align:center;color:var(--m);padding:45px}.row-actions{display:flex;gap:6px}.small{padding:7px 10px;font-size:12px}.modal-bg{display:none;position:fixed;inset:0;z-index:5;background:#000b;place-items:center;padding:18px}.modal-bg.open{display:grid}.modal{width:min(600px,100%);padding:22px;border-radius:18px}.form{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field{display:grid;gap:7px}.field label{font-size:12px;color:var(--m)}.full{grid-column:1/-1}.toast{display:none;position:fixed;bottom:20px;left:20px;padding:13px 16px;background:#171a23;border:1px solid var(--l);border-radius:12px;font-size:13px;z-index:20}.toast.show{display:block}.toast.err{border-color:var(--r)}
@media(max-width:900px){.side{width:74px;padding:18px 9px}.side .brand-text,.side .nav strong,.foot .muted,.foot .btn span{display:none}.side .logo{justify-content:center}.nav{justify-content:center}.content{padding:20px 15px}}@media(max-width:580px){.terminal{margin:16px auto}.termbody{padding:20px;min-height:520px}.term-title{font-size:21px}.content{padding:16px 11px}.grid{grid-template-columns:1fr 1fr;gap:9px}.card{padding:13px}.num{font-size:22px}.form{grid-template-columns:1fr}.full{grid-column:auto}.title{font-size:21px}.actions .btn span{display:none}}
</style></head>'''

def shell(body, js=''):
    return HEAD+'<body>'+body+(f'<script>{js}</script>' if js else '')+'</body></html>'

TERMINAL_HTML=shell('''<div class="terminal glass"><div class="termbar"><div class="dots"><i></i><i></i><i></i></div><div class="langs"><button id="fa" class="active">FA</button><button id="en">EN</button></div><span class="muted mono">technamooz://gateway</span></div><div class="termbody"><div class="logo"><div class="mark">TN</div><span>TECHNAMOOZ <small class="muted">GATEWAY</small></span></div><div class="term-title" id="tt">ترمینال دسترسی امن</div><div class="termline">[<b>OK</b>] encrypted channel initialized</div><div class="termline">[<b>OK</b>] railway edge handshake complete</div><div class="termline">[<span class="red">!!</span>] command authentication required</div><div class="prompt"><span>guest@technamooz:~$</span><input id="cmd" autofocus autocomplete="off" placeholder="type a command..."></div><div id="out" class="terminal-help">دستور <b class="mono">login to panel</b> را وارد کنید.</div></div></div>''','''const cmd=document.getElementById('cmd'),out=document.getElementById('out'),tt=document.getElementById('tt');let lang='fa';const tx={fa:{t:'ترمینال دسترسی امن',h:'دستور <b class="mono">login to panel</b> را وارد کنید.',e:'دستور ناشناخته است.'},en:{t:'Secure access terminal',h:'Type <b class="mono">login to panel</b> to continue.',e:'Unknown command.'}};function setL(x){lang=x;document.documentElement.lang=x;document.documentElement.dir=x==='fa'?'rtl':'ltr';tt.textContent=tx[x].t;out.innerHTML=tx[x].h;document.getElementById('fa').classList.toggle('active',x==='fa');document.getElementById('en').classList.toggle('active',x==='en')}document.getElementById('fa').onclick=()=>setL('fa');document.getElementById('en').onclick=()=>setL('en');cmd.onkeydown=e=>{if(e.key!=='Enter')return;if(cmd.value.trim().toLowerCase()==='login to panel'){out.innerHTML='<b>[OK] opening identity verification...</b>';setTimeout(()=>location.href='/login',300)}else{out.innerHTML='<span class="red">[ERR] '+tx[lang].e+'</span>';cmd.select()}};setL('fa');let auth=false;fetch('/api/me').then(r=>r.json()).then(d=>{if(!d.authenticated)return;auth=true;document.querySelector('.termbar .muted.mono').textContent='technamooz://authenticated-terminal';document.querySelector('.prompt span').textContent='admin@technamooz:~$';tt.textContent='ترمینال اصلی مدیریت';out.innerHTML='دستور <b class=\"mono\">amirparsa-panel-technamooz2026</b> را برای اجرای پنل وارد کنید.'});const old=cmd.onkeydown;cmd.onkeydown=e=>{if(e.key!=='Enter')return;const value=cmd.value.trim();if(auth&&value==='amirparsa-panel-technamooz2026'){out.innerHTML='<b>[OK] unlocking control plane...</b>';fetch('/terminal/unlock',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({command:value})}).then(r=>{if(!r.ok)throw Error('unlock failed');location.href='/panel'}).catch(()=>out.innerHTML='<span class=\"red\">[ERR] unlock failed</span>');return}old(e)};''')

LOGIN_HTML=shell('''<div class="terminal glass"><div class="termbar"><div class="dots"><i></i><i></i><i></i></div><span class="muted mono">identity://verify</span></div><div class="termbody"><div class="logo"><div class="mark">TN</div><span>TECHNAMOOZ <small class="muted">IDENTITY</small></span></div><div class="term-title">تأیید هویت مدیر</div><p class="muted">برای فعال‌سازی ترمینال اصلی وارد شوید.</p><form id="login" style="max-width:470px;display:grid;gap:12px;margin-top:28px"><input id="user" class="input" placeholder="نام کاربری" required autocomplete="username"><input id="pass" class="input" type="password" placeholder="رمز عبور" required autocomplete="current-password"><div style="display:flex;gap:10px;align-items:center"><strong id="cc" class="mono" style="letter-spacing:4px;padding:12px 15px;border-radius:10px;background:#ff36501a"></strong><input id="captcha" class="input" maxlength="5" placeholder="کد امنیتی" required><input id="cid" type="hidden"></div><button id="go" class="btn primary">تأیید هویت و ورود</button><div id="err" class="red" style="min-height:20px;font-size:12px"></div></form></div></div>''','''const $=x=>document.getElementById(x);async function cap(){const d=await fetch('/api/captcha').then(r=>r.json());$('cc').textContent=d.captcha_code;$('cid').value=d.captcha_id;$('captcha').value=''}$('login').onsubmit=async e=>{e.preventDefault();$('go').disabled=true;try{const r=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('user').value,password:$('pass').value,captcha_id:$('cid').value,captcha_code:$('captcha').value})}),d=await r.json();if(!r.ok)throw Error(d.detail||'ورود ناموفق بود');location.href='/terminal'}catch(x){$('err').textContent=x.message;cap()}finally{$('go').disabled=false}};cap();''')

PANEL_HTML=shell('''<div class="app"><aside class="side"><div class="logo"><div class="mark">TN</div><span class="brand-text">TECHNAMOOZ<br><small class="muted">CONTROL PLANE</small></span></div><nav class="navs"><button class="nav active" data-v="home">◈ <strong data-fa="مرکز کنترل" data-en="Overview">مرکز کنترل</strong></button><button class="nav" data-v="links">⌁ <strong data-fa="کانفیگ‌ها" data-en="Configurations">کانفیگ‌ها</strong></button><button class="nav" data-v="subs">◎ <strong data-fa="اشتراک‌ها" data-en="Subscriptions">اشتراک‌ها</strong></button><button class="nav" data-v="activity">◌ <strong data-fa="رویدادها" data-en="Activity">رویدادها</strong></button><button class="nav" data-v="settings">⚙ <strong data-fa="تنظیمات" data-en="Settings">تنظیمات</strong></button></nav><div class="foot"><div class="muted" style="font-size:11px;margin-bottom:10px">secure session · v1</div><button class="btn small" id="logout">↪ <span>خروج</span></button></div></aside><main class="content"><div class="top"><div><h1 class="title" id="title">مرکز کنترل</h1><p class="subtitle" id="sub">نمایش زنده‌ی وضعیت</p></div><div class="actions"><button class="btn small" id="lang">EN</button><button class="btn primary" id="new">＋ <span>کانفیگ جدید</span></button></div></div><div id="view"></div></main></div><div id="mb" class="modal-bg"><div class="modal glass"><div class="section-head"><b>ساخت کانفیگ جدید</b><button class="btn small" id="close">×</button></div><form id="form" class="form"><div class="field"><label>نام</label><input class="input" name="label" required placeholder="Premium user"></div><div class="field"><label>پروتکل</label><select class="select" name="protocol"><option value="vless-ws">VLESS WebSocket</option><option value="trojan-ws">Trojan WebSocket</option><option value="xhttp-packet-up">XHTTP Packet-Up</option><option value="xhttp-stream-up">XHTTP Stream-Up</option></select></div><div class="field"><label>حجم GB</label><input class="input" name="limit_value" type="number" value="0" min="0"></div><div class="field"><label>اعتبار روز</label><input class="input" name="expires_days" type="number" value="30" min="0"></div><div class="field"><label>محدودیت IP</label><input class="input" name="ip_limit" type="number" value="0" min="0"></div><div class="field"><label>سرعت Mbps</label><input class="input" name="speed_limit_value" type="number" value="0" min="0"></div><div class="field full"><label>یادداشت</label><input class="input" name="note"></div><div class="field full"><button class="btn primary">ساخت و تولید لینک</button></div></form></div></div><div id="toast" class="toast"></div>''','''const $=x=>document.getElementById(x),api=async(u,o={})=>{const r=await fetch(u,o);if(r.status===401){location.href='/login';throw Error('session expired')}const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.detail||'request failed');return d};let lang='fa',v='home';const meta={fa:{home:['مرکز کنترل','نمایش زنده‌ی وضعیت'],links:['مدیریت کانفیگ‌ها','ساخت و کنترل لینک‌های دسترسی'],subs:['اشتراک‌ها','مدیریت گروه‌های اشتراکی'],activity:['رویدادها','ردیابی فعالیت‌های سیستم'],settings:['تنظیمات','کنترل حساب و سرویس‌ها']},en:{home:['Control center','Live service overview'],links:['Configurations','Create and control access links'],subs:['Subscriptions','Manage subscription groups'],activity:['Activity','Recent system events'],settings:['Settings','Account and service controls']}};function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function fmt(n){n=Number(n||0);return n<1024?n+' B':n<1048576?(n/1024).toFixed(1)+' KB':n<1073741824?(n/1048576).toFixed(1)+' MB':(n/1073741824).toFixed(2)+' GB'}function toast(x,e=false){$('toast').textContent=x;$('toast').className='toast show'+(e?' err':'');setTimeout(()=>$('toast').className='toast',2500)}function metaSet(){const m=meta[lang][v];$('title').textContent=m[0];$('sub').textContent=m[1];document.documentElement.lang=lang;document.documentElement.dir=lang==='fa'?'rtl':'ltr';document.querySelectorAll('[data-fa]').forEach(x=>x.textContent=x.dataset[lang]);$('lang').textContent=lang==='fa'?'EN':'FA'}function go(x){v=x;metaSet();document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.v===v));({home:home,links:links,subs:subs,activity:activity,settings:settings}[v])().catch(e=>{$('view').innerHTML='<div class="card glass empty">'+esc(e.message)+'</div>'})}async function home(){const[s,a,c]=await Promise.all([api('/stats'),api('/api/activity'),api('/api/connections')]);$('view').innerHTML='<div class="grid">'+[['◈',s.total_links,'کل کانفیگ‌ها'],['✓',s.active_links,'فعال'],['↯',s.active_connections,'اتصال زنده'],['⇅',fmt(s.total_bytes),'ترافیک مصرفی']].map(x=>'<div class="card glass"><div class="icon">'+x[0]+'</div><div class="num">'+(x[1]||0)+'</div><div class="label">'+x[2]+'</div></div>').join('')+'</div><div class="section grid" style="grid-template-columns:1.2fr .8fr"><div class="card glass"><div class="section-head"><b>Hourly traffic</b><span class="pill">LIVE</span></div><div style="height:150px;display:flex;align-items:end;gap:7px">'+Array.from({length:18},(_,i)=>'<i style="flex:1;height:'+Math.max(8,((s.hourly_traffic||{})[String(i)]||0)%100)+'%;background:linear-gradient(#ff3650,#a60e2833);border-radius:6px 6px 2px 2px"></i>').join('')+'</div></div><div class="card glass"><div class="section-head"><b>Live connections</b><span class="muted">'+(c.count||0)+'</span></div>'+((c.connections||[]).slice(0,5).map(x=>'<div style="padding:11px 0;border-bottom:1px solid var(--l)"><b>'+esc(x.label)+'</b><div class="muted mono">'+esc(x.ip)+' · '+esc(x.transport)+'</div></div>').join('')||'<div class="empty">No active connections</div>')+'</div></div><div class="section card glass"><div class="section-head"><b>Recent activity</b><button class="btn small" onclick="go(\'activity\')">View all</button></div>'+((a.logs||[]).slice(0,6).map(x=>'<div style="padding:10px 0;border-bottom:1px solid var(--l)">'+esc(x.message)+'<div class="muted">'+esc(x.time||'')+'</div></div>').join('')||'<div class="empty">No activity</div>')+'</div>'}async function links(){const d=await api('/api/links');$('view').innerHTML='<div class="card glass table-wrap"><table class="table"><thead><tr><th>نام</th><th>پروتکل</th><th>وضعیت</th><th>مصرف</th><th>انقضا</th><th>عملیات</th></tr></thead><tbody>'+((d.links||[]).map(x=>'<tr><td><b>'+esc(x.label)+'</b><div class="muted mono">'+x.uuid.slice(0,16)+'…</div></td><td><span class="pill">'+esc(x.protocol)+'</span></td><td><span class="pill '+(!x.active||x.expired?'off':'')+'">'+(x.expired?'EXPIRED':x.active?'ACTIVE':'DISABLED')+'</span></td><td>'+fmt(x.used_bytes)+(x.limit_bytes?' / '+fmt(x.limit_bytes):'')+'</td><td>'+esc(x.expires_at||'∞')+'</td><td><div class="row-actions"><button class="btn small" onclick="copy('+JSON.stringify(x.vless_link)+')">کپی</button><button class="btn small" onclick="renew(\''+x.uuid+'\')">+30d</button><button class="btn small red" onclick="removeL(\''+x.uuid+'\')">حذف</button></div></td></tr>').join('')||'<tr><td colspan="6" class="empty">کانفیگی وجود ندارد.</td></tr>')+'</tbody></table></div>'}async function subs(){const d=await api('/api/subs');$('view').innerHTML='<div class="section-head"><span class="muted">'+(d.subs||[]).length+' groups</span><button class="btn primary" onclick="newSub()">＋ ساخت گروه</button></div><div class="grid">'+((d.subs||[]).map(x=>'<div class="card glass"><div class="section-head"><b>'+esc(x.name)+'</b><span class="pill">'+(x.active_count||0)+' active</span></div><p class="muted">'+esc(x.desc||'بدون توضیح')+'</p><div class="mono" style="font-size:11px;word-break:break-all">'+esc(x.public_url||'')+'</div><button class="btn small" style="margin-top:14px" onclick="copy('+JSON.stringify(x.public_url||'')+')">کپی لینک</button></div>').join('')||'<div class="card glass empty">گروهی وجود ندارد.</div>')+'</div>'}async function activity(){const d=await api('/api/activity');$('view').innerHTML='<div class="card glass">'+((d.logs||[]).map(x=>'<div style="padding:12px 0;border-bottom:1px solid var(--l)">'+esc(x.message)+'<div class="muted">'+esc(x.time||'')+' · '+esc(x.kind||'system')+'</div></div>').join('')||'<div class="empty">No activity</div>')+'</div>'}async function settings(){const d=await api('/api/telegram/status');$('view').innerHTML='<div class="grid" style="grid-template-columns:1fr 1fr"><div class="card glass"><b>حساب مدیر</b><p class="muted">مدیریت credential با endpoint امن فعلی انجام می‌شود.</p></div><div class="card glass"><b>Telegram service</b><p class="muted">وضعیت: <span class="pill '+(d.running?'':'off')+'">'+(d.running?'ONLINE':'OFFLINE')+'</span></p></div></div>'}function copy(x){navigator.clipboard.writeText(x).then(()=>toast('کپی شد / Copied')).catch(()=>toast('کپی ناموفق بود',true))}async function renew(id){try{await api('/api/links/'+id+'/renew',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({days:30})});toast('تمدید شد');go('links')}catch(e){toast(e.message,true)}}async function removeL(id){if(!confirm('حذف شود؟'))return;try{await api('/api/links/'+id,{method:'DELETE'});toast('حذف شد');go('links')}catch(e){toast(e.message,true)}}async function newSub(){const n=prompt('نام گروه');if(!n)return;try{await api('/api/subs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:n,desc:''})});toast('ساخته شد');go('subs')}catch(e){toast(e.message,true)}}document.querySelectorAll('.nav').forEach(n=>n.onclick=()=>go(n.dataset.v));$('lang').onclick=()=>{lang=lang==='fa'?'en':'fa';go(v)};$('logout').onclick=async()=>{await api('/api/logout',{method:'POST'});location.href='/'};$('new').onclick=()=>$('mb').classList.add('open');$('close').onclick=()=>$('mb').classList.remove('open');$('form').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));['limit_value','expires_days','ip_limit','speed_limit_value'].forEach(k=>b[k]=Number(b[k]||0));try{await api('/api/links',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)});$('mb').classList.remove('open');e.target.reset();toast('کانفیگ ساخته شد');go('links')}catch(x){toast(x.message,true)}};go('home');''')
DASHBOARD_HTML=PANEL_HTML

def get_public_page_html(uuid_key: str)->str:
    u=escape(uuid_key,quote=True)
    return shell(f'''<div class="terminal glass"><div class="termbar"><div class="dots"><i></i><i></i><i></i></div><span class="muted">PUBLIC SUBSCRIPTION</span></div><div class="termbody"><div class="logo"><div class="mark">TN</div><span>TECHNAMOOZ</span></div><div id="sub" style="margin-top:30px">در حال دریافت اشتراک…</div></div></div>''',f'''const b=document.getElementById('sub');fetch('/api/public/sub/{u}').then(r=>r.json()).then(d=>{{if(d.locked){{b.innerHTML='<h2>اشتراک محافظت شده است</h2>';return}}b.innerHTML='<h2>'+String(d.name||'Subscription')+'</h2><p class="muted">'+String(d.desc||'')+'</p>'+(d.links||[]).map(x=>'<div class="card glass" style="margin-top:12px"><b>'+String(x.label||'Config')+'</b><div class="muted">'+String(x.protocol||'')+' · '+String(x.used_fmt||'')+'</div><button class="btn small" onclick="navigator.clipboard.writeText('+JSON.stringify(x.vless_link||'')+')">کپی لینک</button></div>').join('')}}).catch(()=>b.innerHTML='<span class="red">خطا در دریافت اشتراک</span>');''')
